arguments.command:
cd /tmp/vally-eval-trial-rzSKKi
mkdir -p tests/CheckoutPricing.UnitTests/Checkout
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public decimal Execute(string customerTier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerCheckoutTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerCheckoutTests
{
    [Fact]
    public void Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var total = new CalculatePayableTotal().Execute("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

